SELECT *
FROM dc_customer_information
WHERE del_flag = 0

    AND lawyer_id = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}

SELECT package_type, COUNT(1) as count FROM dc_customer_information WHERE del_flag = 0
AND lawyer_id = #{lawyerId}
GROUP BY package_type

SELECT * FROM dc_customer_information WHERE del_flag = 0 AND expire_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 2 DAY) AND DATE_ADD(CURDATE(), INTERVAL 2 DAY)
AND lawyer_id = #{lawyerId}
AND create_dept IN
#{deptId}

SELECT * FROM dc_customer_information WHERE del_flag = 0 AND balance > 0
AND lawyer_id = #{lawyerId}
AND create_dept IN
#{deptId}

SELECT * FROM dc_customer_information WHERE id NOT IN ( SELECT customer_id FROM dc_customer_tracking WHERE del_flag = 0 AND tracking_time >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_customer_out_visit WHERE del_flag = 0 AND visit_time >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_insurance_case WHERE del_flag = 0 AND order_date >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_debt_case WHERE del_flag = 0 AND filing_date >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_customer_job_order WHERE del_flag = 0 AND create_time >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND id NOT IN ( SELECT customer_id FROM dc_case_tracking WHERE del_flag = 0 AND tracking_time >= DATE_SUB( CURDATE(), INTERVAL 20 DAY )) AND del_flag = 0
AND lawyer_id = #{lawyerId}
AND create_dept IN
#{deptId}
